// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // The test contract deployed c, so address(this) is the current owner.
        // Only admissible calls are those from the owner; make the call as the owner.
        vm.assume(newOwner != address(this));
        vm.prank(address(this));
        bool ok = c.setOwner(newOwner);
        assertTrue(ok && c.owner() == newOwner);
    }
}
